                early_cached_search_partial_read_bytes,
            )
        } else {
            read_request_standard(&mut stream, &mut buffer)
                .map(|request| request.map(ReadOutcome::Parsed))
        } {
            Ok(Some(request)) => request,
            Ok(None) => {
                if let Some(stats) = stats.as_ref() {
                    stats.flush_snapshot();
                }
