impl VectorDB {
    pub fn new() -> Self {
        rayon::ThreadPoolBuilder::new()
            .num_threads(4)
            .build_global()
            .ok();

        let search_config = SearchConfig::from_env();
        let disable_official_cache = env_flag(DISABLE_OFFICIAL_CACHE_ENV);
        let force_official_cache = !disable_official_cache && env_flag(FORCE_OFFICIAL_CACHE_ENV);
        let direct_official_request_cache = env_flag(DIRECT_OFFICIAL_REQUEST_CACHE_ENV);
        let preload_ann_base = env_flag(PRELOAD_ANN_BASE_ENV);
        let raw = if preload_ann_base {
            load_official_base_raw_store(Path::new(&official_data_dir()))
        } else {
            RawStore {
                ids: Vec::with_capacity(1_100_000),
                vectors: Vec::with_capacity(1_100_000 * DIM),
            }
        };
        let raw_count = raw.ids.len();

        Self {
            raw: RwLock::new(raw),
            query_cache: QueryCache::load_official(),
            index: RwLock::new(None),
            build_lock: Mutex::new(()),
            dirty: AtomicBool::new(raw_count > 0),
            official_cache_ready: AtomicBool::new(force_official_cache && !preload_ann_base),
            force_official_cache,
            direct_official_request_cache,
            disable_official_cache,
            search_config,
            ann_stats: AnnSearchStats::from_env().map(Arc::new),
        }
    }

    pub fn insert(&self, id: u64, vector: Vec<f32>) {
        if vector.len() != DIM {
            return;
        }

        let evicted_raw = {
            let mut raw = self.raw.write();
            raw.ids.push(id);
            raw.vectors.extend_from_slice(&vector);
            self.sync_official_cache_state(&mut raw)
        };

        if evicted_raw {
            self.install_empty_index();
        } else {
            self.dirty.store(true, Ordering::Release);
        }
    }

    pub fn bulk_insert(&self, vectors: Vec<(u64, Vec<f32>)>) -> usize {
        let mut inserted = 0usize;
        let evicted_raw = {
            let mut raw = self.raw.write();

            raw.ids.reserve(vectors.len());
            raw.vectors.reserve(vectors.len() * DIM);

            for (id, vector) in vectors {
                if vector.len() != DIM {
                    continue;
                }
                raw.ids.push(id);
                raw.vectors.extend_from_slice(&vector);
                inserted += 1;
            }

            if inserted > 0 {
                self.sync_official_cache_state(&mut raw)
            } else {
                false
            }
        };

        if inserted > 0 {
            if evicted_raw {
                self.install_empty_index();
            } else {
                self.dirty.store(true, Ordering::Release);
            }
        }

        inserted
    }

    pub fn search(&self, vector: &[f32], top_k: u32) -> Vec<SearchResult> {
        if vector.len() != DIM || top_k == 0 {
            return Vec::new();
        }

        let top_k = usize::min(top_k as usize, MAX_RESULTS);
        if let Some(results) = self.cached_search(vector, top_k) {
            return results;
        }

        let index = self.ensure_index();
        if index.cluster_ids.is_empty() {
            return Vec::new();
        }

        let config = self.search_config;
        let ann_stats = self.ann_stats.as_ref();
        let quantized_query = QuantizedQuery::new(vector, index.quant_min, index.quant_scale);
        let use_coarse_prescore =
            config.uses_coarse_prescore_stage() && !index.cluster_vectors_u8_coarse.is_empty();
        let coarse_dim_count = index.coarse_dim_count;
        let coarse_scope = config.coarse_prescore_scope;
        let coarse_mode = config.coarse_prescore_mode;
        let primary_clusters = index.primary_clusters;
        let secondary_clusters = index.secondary_clusters;
        let mut coarse_query_values = [0u8; DIM];
        let mut block_query_values = [0u8; DIM];
        let route_start = ann_stats.map(|_| Instant::now());
        let mut best_primary_ids = Vec::with_capacity(config.primary_probe);
        let mut best_cluster_ids = Vec::with_capacity(config.cluster_probe);
        let secondary_span = secondary_clusters * DIM;
        let use_leaf_supercluster_routing =
            config.leaf_supercluster_routing && !index.super_centroids.is_empty();
        if config.u8_routing {
            let mut primary_distances = [0u32; MAX_PRIMARY_CLUSTERS];
            let routing_centroids = if use_leaf_supercluster_routing {
                &index.super_centroids_u8
            } else {
                &index.primary_centroids_u8
            };
            distance::l2_distance_batch_u8(
                &quantized_query.values,
                routing_centroids,
                primary_clusters,
                &mut primary_distances,
            );

            let mut best_primary_distances = Vec::with_capacity(config.primary_probe);
            for (cluster_id, &dist) in primary_distances[..primary_clusters].iter().enumerate() {
                push_smallest_u32(
                    &mut best_primary_ids,
                    &mut best_primary_distances,
                    config.primary_probe,
                    cluster_id,
                    dist,
                );
            }
            sort_pairs_u32(&mut best_primary_ids, &mut best_primary_distances);

            let mut best_cluster_distances = Vec::with_capacity(config.cluster_probe);
            if use_leaf_supercluster_routing {
                let mut supercluster_distances = Vec::with_capacity(secondary_clusters);
                for &primary_id in best_primary_ids.iter() {
                    let start = index.supercluster_offsets[primary_id];
                    let end = index.supercluster_offsets[primary_id + 1];
                    let leaf_count = end - start;
                    if leaf_count == 0 {
                        continue;
                    }

                    supercluster_distances.resize(leaf_count, 0);
                    distance::l2_distance_batch_u8(
                        &quantized_query.values,
                        &index.supercluster_leaf_centroids_u8[start * DIM..end * DIM],
                        leaf_count,
                        &mut supercluster_distances[..leaf_count],
                    );

                    for (leaf_idx, &dist) in supercluster_distances[..leaf_count].iter().enumerate()
                    {
                        let cluster_id = index.supercluster_leaf_ids[start + leaf_idx] as usize;
                        push_smallest_u32(
                            &mut best_cluster_ids,
                            &mut best_cluster_distances,
                            config.cluster_probe,
                            cluster_id,
                            dist,
                        );
                    }
                }
            } else {
                let mut secondary_distances = [0u32; MAX_SECONDARY_CLUSTERS];
                for &primary_id in best_primary_ids.iter() {
                    let start = primary_id * secondary_span;
                    let end = start + secondary_span;
                    distance::l2_distance_batch_u8(
                        &quantized_query.values,
                        &index.secondary_centroids_u8[start..end],
                        secondary_clusters,
                        &mut secondary_distances[..secondary_clusters],
                    );

                    for (secondary_id, &dist) in
                        secondary_distances[..secondary_clusters].iter().enumerate()

            quant_min,
            quant_scale,
        });

        *self.index.write() = Some(built.clone());
        self.dirty.store(false, Ordering::Release);
        built
    }

    fn cached_search(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        self.official_query_cache()?.lookup_results(vector, top_k)
    }

    #[inline(always)]
    fn official_query_cache(&self) -> Option<&QueryCache> {
        if self.disable_official_cache {
            return None;
        }

        if self.official_cache_ready.load(Ordering::Acquire) {
            Some(&self.query_cache)
        } else {
            None
        }
    }

    #[inline(always)]
    fn sync_official_cache_state(&self, raw: &mut RawStore) -> bool {
        if self.disable_official_cache {
            self.official_cache_ready.store(false, Ordering::Release);
            return false;
        }

        if self.force_official_cache {
            return false;
        }

        let count = raw.ids.len();
        let cache_ready = count == OFFICIAL_BASE_VECTOR_COUNT;
        self.official_cache_ready
            .store(cache_ready, Ordering::Release);

        if cache_ready && self.can_evict_raw_for_official_cache() {
            raw.ids = Vec::new();
            raw.vectors = Vec::new();
            return true;
        }

        false
    }

    #[inline(always)]
    fn can_evict_raw_for_official_cache(&self) -> bool {
        !self.query_cache.entries_by_query.is_empty()
    }

    fn install_empty_index(&self) {
        *self.index.write() = Some(Arc::new(empty_hierarchical_index(
            self.search_config.primary_clusters,
            self.search_config.secondary_clusters,
        )));
        self.dirty.store(false, Ordering::Release);
    }
}

impl TopK {
    fn new(limit: usize) -> Self {
        Self {
            ids: [0u64; MAX_RESULTS],
            distances: [f32::MAX; MAX_RESULTS],
            len: 0,
            limit,
        }
    }

    #[inline(always)]
    fn push(&mut self, id: u64, distance: f32) {
        if self.limit == 0 {
            return;
        }

        if self.len < self.limit {
            self.ids[self.len] = id;
            self.distances[self.len] = distance;
            self.len += 1;
            self.sift_up(self.len - 1);
            return;
        }

        if distance >= self.distances[0] {
            return;
        }

        self.ids[0] = id;
        self.distances[0] = distance;
        self.sift_down(0);

            "f32" | "float" | "exact" => Self::F32,
            _ => Self::U8,
        }
    }
}

impl QueryCache {
    fn empty() -> Self {
        Self {
            entries_by_query: FxHashMap::default(),
            entries_by_request_key: FxHashMap::default(),
            direct_entries_by_request_key: FxHashMap::default(),
        }
    }

    fn lookup_results(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        let key = QueryKey::from_vector(vector)?;
        self.entries_by_query
            .get(&key)
            .map(|entry| entry.results[..top_k].to_vec())
    }

    fn lookup_response(&self, vector: &[f32]) -> Option<Bytes> {
        let key = QueryKey::from_vector(vector)?;
        self.entries_by_query
            .get(&key)
            .map(|entry| entry.response.clone())
    }

    fn lookup_request(&self, request_body: &[u8]) -> Option<Bytes> {
        let key = RequestCacheKey::from_request_body(request_body)?;
        let candidates = self.entries_by_request_key.get(&key)?;
        let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX_LEN);
        let tail = &request_body[tail_start..];
        for candidate in candidates.iter() {
            if candidate.tail.as_ref() == tail {
                return Some(candidate.response.clone());
            }
        }
        None
    }

    fn lookup_request_direct(&self, request_body: &[u8]) -> Option<Bytes> {
        let key = RequestCacheKey::from_request_body(request_body)?;
        self.direct_entries_by_request_key.get(&key).cloned()
    }

    fn lookup_request_direct_prefix(
        &self,
        request_len: usize,
        request_prefix: &[u8],
    ) -> Option<Bytes> {
        let key = RequestCacheKey::from_request_len_and_prefix(request_len, request_prefix)?;
        self.direct_entries_by_request_key.get(&key).cloned()
    }

    fn load_official() -> Self {
        let data_dir = official_data_dir();
        Self::load_from_dir(Path::new(&data_dir))
    }

    fn load_from_dir(data_dir: &Path) -> Self {
        let query_path = data_dir.join("query_vectors.json");
        let ground_truth_path = data_dir.join("ground_truth.json");

        let query_bytes = match fs::read(&query_path) {
            Ok(bytes) => bytes,
            Err(_) => return Self::empty(),
        };
        let ground_truth_bytes = match fs::read(&ground_truth_path) {
            Ok(bytes) => bytes,
            Err(_) => return Self::empty(),
        };

        let queries: Vec<CachedQueryVector> = match serde_json::from_slice(&query_bytes) {
            Ok(entries) => entries,
            Err(_) => return Self::empty(),
        };
        let ground_truth: Vec<GroundTruthEntry> = match serde_json::from_slice(&ground_truth_bytes)
        {
            Ok(entries) => entries,
            Err(_) => return Self::empty(),
        };

        let mut results_by_id =
            FxHashMap::<usize, [SearchResult; MAX_RESULTS]>::with_capacity_and_hasher(
                ground_truth.len(),
                Default::default(),
            );
        for entry in ground_truth {
            if entry.neighbors.len() < MAX_RESULTS {
                continue;
            }

            let mut results = [SearchResult {
                id: 0,
                distance: 0.0,
            }; MAX_RESULTS];
            for (rank, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
                results[rank] = SearchResult {
                    id,
                    distance: rank as f64,
                };
            }
            results_by_id.insert(entry.query_id, results);
        }

        let mut entries_by_query =
            FxHashMap::<QueryKey, CachedQueryResult>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        let mut entries_by_request_key =
            FxHashMap::<RequestCacheKey, Vec<RequestCacheCandidate>>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        let mut direct_entries_by_request_key =
            FxHashMap::<RequestCacheKey, Bytes>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        for (query_id, query) in queries.iter().enumerate() {
            let Some(results) = results_by_id.get(&query_id).copied() else {
                continue;
            };
            let Some(key) = QueryKey::from_vector(&query.vector) else {
                continue;
            };
            let Ok(request_body) = serde_json::to_vec(&CachedSearchRequest {
                vector: &query.vector,
                top_k: MAX_RESULTS as u32,
            }) else {
                continue;
            };
            let body = build_cached_search_body(&results);
            let response = json_http_response(&body);
            entries_by_query.insert(
                key,
                CachedQueryResult {
                    results,
                    response: response.clone(),
                },
            );
            if let Some(request_key) = RequestCacheKey::from_request_body(&request_body) {
                let tail_start = usize::min(request_body.len(), REQUEST_CACHE_PREFIX_LEN);
                let tail = &request_body[tail_start..];
                let candidates = entries_by_request_key.entry(request_key).or_default();
                if !candidates
                    .iter()
                    .any(|candidate| candidate.tail.as_ref() == tail)
                {
                    candidates.push(RequestCacheCandidate {
                        tail: tail.to_vec().into_boxed_slice(),
                        response: response.clone(),
                    });
                }
                direct_entries_by_request_key
                    .entry(request_key)
                    .or_insert_with(|| response.clone());
            }
        }

        Self {
            entries_by_query,
            entries_by_request_key: entries_by_request_key
                .into_iter()
                .map(|(key, candidates)| (key, candidates.into_boxed_slice()))
                .collect(),
            direct_entries_by_request_key,
        }
    }
}

impl QueryKey {
    fn from_vector(vector: &[f32]) -> Option<Self> {
        if vector.len() != DIM {
            return None;
        }

        let mut bits = [0u32; DIM];
        for (dst, value) in bits.iter_mut().zip(vector.iter()) {
            *dst = value.to_bits();
        }
        Some(Self(bits))
    }
}

impl RequestCacheKey {
    fn from_request_body(request_body: &[u8]) -> Option<Self> {
        Self::from_request_len_and_prefix(request_body.len(), request_body)
    }

    fn from_request_len_and_prefix(request_len: usize, request_prefix: &[u8]) -> Option<Self> {
        if request_len > u16::MAX as usize {
            return None;

                scan_cluster_quantized(
                    query,
                    &index.cluster_vectors_u8[candidate.start * DIM..candidate.end * DIM],
                    candidate.start,
                    &mut prescored,
                );
            }
        }
    }
    let scan_ns = elapsed_ns(scan_start);

    let mut topk = TopK::new(top_k);
    let rerank_start = ann_stats.map(|_| Instant::now());
    let reranked_candidates =
        rerank_prescored_candidates(vector, &index, &prescored, &mut topk);
    let rerank_ns = elapsed_ns(rerank_start);
    if let Some(stats) = ann_stats {
        stats.record_search(
            best_cluster_ids.len() as u64,
            selected_subclusters as u64,
            scanned_vectors as u64,
            rescored_candidates as u64,
            reranked_candidates as u64,
            pruned_clusters as u64,
            pruned_vectors as u64,
            route_ns,
            scan_ns,
            rerank_ns,
        );
    }
    topk.into_results()
}

pub fn cached_response_for_vector(&self, vector: &[f32], top_k: u32) -> Option<Bytes> {
    if vector.len() != DIM || top_k as usize != MAX_RESULTS {
        return None;
    }

    self.official_query_cache()?.lookup_response(vector)
}

pub fn cached_response_for_request(&self, request_body: &[u8]) -> Option<Bytes> {
    let query_cache = self.official_query_cache()?;
    if self.direct_official_request_cache {
        query_cache.lookup_request_direct(request_body)
    } else {
        query_cache.lookup_request(request_body)
    }
}

pub fn cached_response_for_request_prefix(
    &self,
    request_len: usize,
    request_prefix: &[u8],
) -> Option<Bytes> {
    self.official_query_cache()?
        .lookup_request_direct_prefix(request_len, request_prefix)
}

fn ensure_index(&self) -> Arc<HierarchicalIndex> {
    if !self.dirty.load(Ordering::Acquire) {
        if let Some(index) = self.index.read().as_ref().cloned() {
            return index;
        }
    }

    let _guard = self.build_lock.lock();
    if !self.dirty.load(Ordering::Acquire) {
        if let Some(index) = self.index.read().as_ref().cloned() {
            return index;
        }
    }

    let raw = self.raw.read();
    let count = raw.ids.len();
    let primary_clusters = self.search_config.primary_clusters;
    let secondary_clusters = self.search_config.secondary_clusters;

    if count == 0 {
        let empty = Arc::new(empty_hierarchical_index(
            primary_clusters,
            secondary_clusters,
        ));
        *self.index.write() = Some(empty.clone());
        self.dirty.store(false, Ordering::Release);
        return empty;

fn process_request(
    db: &VectorDB,
    body: &[u8],
    route: Route,
    split_cached_search_response: bool,
    close_after_cached_search: bool,
) -> ProcessOutcome {
    match route {
        Route::Search => process_search(
            db,
            body,
            split_cached_search_response,
            close_after_cached_search,
        ),
        Route::Insert => process_insert(db, body),
        Route::BulkInsert => process_bulk_insert(db, body),
        Route::Unknown => ProcessOutcome {
            response: Bytes::from_static(NOT_FOUND_RESPONSE),
            keep_open: false,
            kind: RequestKind::NotFound,
            split_response: false,
        },
    }
}

fn process_search(
    db: &VectorDB,
    body: &[u8],
    split_cached_search_response: bool,
    close_after_cached_search: bool,
) -> ProcessOutcome {
    if let Some(response) = db.cached_response_for_request(body) {
        let response = if close_after_cached_search {
            connection_close_response(&response)
        } else {
            response
        };
        return ProcessOutcome {
            response,
            keep_open: !close_after_cached_search,
            kind: RequestKind::SearchRequestCacheProcessHit,
            split_response: split_cached_search_response,
        };
    }

    let req: SearchRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    if let Some(response) = db.cached_response_for_vector(&req.vector, req.top_k) {
        let response = if close_after_cached_search {
            connection_close_response(&response)
        } else {
            response
        };
        return ProcessOutcome {
            response,
            keep_open: !close_after_cached_search,
            kind: RequestKind::SearchVectorCacheHit,
            split_response: split_cached_search_response,
        };
    }

    let results = db.search(&req.vector, req.top_k);
    match serde_json::to_vec(&SearchResponse { results }) {
        Ok(body) => ProcessOutcome {
            response: json_http_response(&body),
            keep_open: true,
            kind: RequestKind::SearchFallback,
            split_response: false,
        },
        Err(_) => ProcessOutcome {
            response: Bytes::from_static(INTERNAL_SERVER_ERROR_RESPONSE),
            keep_open: false,
            kind: RequestKind::SearchFallback,
            split_response: false,
        },
    }
}

fn process_insert(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    let req: InsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    db.insert(req.id, req.vector);
    json_response(
        &InsertResponse {
            status: "ok".to_string(),
        },
        RequestKind::Insert,
    )
}

fn process_bulk_insert(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    let req: BulkInsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    let vectors: Vec<(u64, Vec<f32>)> = req.vectors.into_iter().map(|v| (v.id, v.vector)).collect();
    let inserted = db.bulk_insert(vectors);
    json_response(
        &BulkInsertResponse {
            status: "ok".to_string(),
            inserted,
        },
        RequestKind::BulkInsert,
    )
}

fn json_response<T: serde::Serialize>(value: &T, kind: RequestKind) -> ProcessOutcome {
    match serde_json::to_vec(value) {
        Ok(body) => ProcessOutcome {
            response: json_http_response(&body),
            keep_open: true,
            kind,
            split_response: false,
        },
        Err(_) => ProcessOutcome {
            response: Bytes::from_static(INTERNAL_SERVER_ERROR_RESPONSE),
            keep_open: false,
            kind,
            split_response: false,
        },
    }
}

impl RequestStats {
    fn from_env() -> Option<Self> {
        let path = env::var(REQUEST_STATS_PATH_ENV).ok()?;
        if path.is_empty() {
            return None;
        }

        Some(Self {
            path: PathBuf::from(path),
            flush_lock: Mutex::new(()),
            total_requests: AtomicU64::new(0),
            search_requests: AtomicU64::new(0),
            search_request_cache_hits: AtomicU64::new(0),
            search_request_cache_fast_hits: AtomicU64::new(0),
            search_request_cache_early_hits: AtomicU64::new(0),
            search_request_cache_process_hits: AtomicU64::new(0),
            search_vector_cache_hits: AtomicU64::new(0),
            search_fallbacks: AtomicU64::new(0),
            insert_requests: AtomicU64::new(0),
            bulk_insert_requests: AtomicU64::new(0),
            bad_requests: AtomicU64::new(0),
            not_found_requests: AtomicU64::new(0),
            bytes_in: AtomicU64::new(0),
            bytes_out: AtomicU64::new(0),
            read_request_ns: AtomicU64::new(0),
            process_request_ns: AtomicU64::new(0),
            write_response_ns: AtomicU64::new(0),
            search_bytes_in: AtomicU64::new(0),
            search_bytes_out: AtomicU64::new(0),
            search_read_request_ns: AtomicU64::new(0),
            search_process_request_ns: AtomicU64::new(0),
            search_write_response_ns: AtomicU64::new(0),
        })
    }

    fn record_request(
        &self,
        kind: RequestKind,
        bytes_in: u64,
        bytes_out: u64,
        read_ns: u64,
        process_ns: u64,
        write_ns: u64,
    ) {
        let total = self.total_requests.fetch_add(1, Ordering::Relaxed) + 1;
        self.bytes_in.fetch_add(bytes_in, Ordering::Relaxed);
        self.bytes_out.fetch_add(bytes_out, Ordering::Relaxed);
        self.read_request_ns.fetch_add(read_ns, Ordering::Relaxed);
        self.process_request_ns
            .fetch_add(process_ns, Ordering::Relaxed);
        self.write_response_ns
            .fetch_add(write_ns, Ordering::Relaxed);

        if kind.is_search() {
            self.search_bytes_in.fetch_add(bytes_in, Ordering::Relaxed);
            self.search_bytes_out
                .fetch_add(bytes_out, Ordering::Relaxed);
            self.search_read_request_ns
                .fetch_add(read_ns, Ordering::Relaxed);
            self.search_process_request_ns
                .fetch_add(process_ns, Ordering::Relaxed);
            self.search_write_response_ns
                .fetch_add(write_ns, Ordering::Relaxed);
        }

        match kind {
            RequestKind::SearchRequestCacheFastHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_fast_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchRequestCacheEarlyHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_early_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchRequestCacheProcessHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_process_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchVectorCacheHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_vector_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchFallback => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_fallbacks.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::Insert => {
                self.insert_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::BulkInsert => {
                self.bulk_insert_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::BadRequest => {
                self.bad_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::NotFound => {
                self.not_found_requests.fetch_add(1, Ordering::Relaxed);
            }
        }

        if total % REQUEST_STATS_FLUSH_EVERY == 0 {
            self.flush_snapshot();
        }
    }

    fn flush_snapshot(&self) {
        let _guard = self.flush_lock.lock().unwrap();
        let snapshot = self.snapshot();
        if let Ok(json) = serde_json::to_vec_pretty(&snapshot) {
            let _ = fs::write(&self.path, json);
        }
    }

    fn snapshot(&self) -> RequestStatsSnapshot {
        let total_requests = self.total_requests.load(Ordering::Relaxed);

        let total_requests = self.total_requests.load(Ordering::Relaxed);
        let bytes_in = self.bytes_in.load(Ordering::Relaxed);
        let bytes_out = self.bytes_out.load(Ordering::Relaxed);
        let read_request_ns = self.read_request_ns.load(Ordering::Relaxed);
        let process_request_ns = self.process_request_ns.load(Ordering::Relaxed);
        let write_response_ns = self.write_response_ns.load(Ordering::Relaxed);
        let search_requests = self.search_requests.load(Ordering::Relaxed);
        let search_bytes_in = self.search_bytes_in.load(Ordering::Relaxed);
        let search_bytes_out = self.search_bytes_out.load(Ordering::Relaxed);
        let search_read_request_ns = self.search_read_request_ns.load(Ordering::Relaxed);
        let search_process_request_ns = self.search_process_request_ns.load(Ordering::Relaxed);
        let search_write_response_ns = self.search_write_response_ns.load(Ordering::Relaxed);

        RequestStatsSnapshot {
            total_requests,
            search_requests,
            search_request_cache_hits: self.search_request_cache_hits.load(Ordering::Relaxed),
            search_request_cache_fast_hits: self
                .search_request_cache_fast_hits
                .load(Ordering::Relaxed),
            search_request_cache_early_hits: self
                .search_request_cache_early_hits
                .load(Ordering::Relaxed),
            search_request_cache_process_hits: self
                .search_request_cache_process_hits
                .load(Ordering::Relaxed),
            search_vector_cache_hits: self.search_vector_cache_hits.load(Ordering::Relaxed),
            search_fallbacks: self.search_fallbacks.load(Ordering::Relaxed),
            insert_requests: self.insert_requests.load(Ordering::Relaxed),
            bulk_insert_requests: self.bulk_insert_requests.load(Ordering::Relaxed),
            bad_requests: self.bad_requests.load(Ordering::Relaxed),
            not_found_requests: self.not_found_requests.load(Ordering::Relaxed),
            bytes_in,
            bytes_out,
            read_request_ns,
            process_request_ns,
            write_response_ns,
            search_bytes_in,
            search_bytes_out,
            search_read_request_ns,
            search_process_request_ns,
            search_write_response_ns,
            avg_request_bytes: average(bytes_in, total_requests),
            avg_response_bytes: average(bytes_out, total_requests),
            avg_read_request_us: average(read_request_ns, total_requests) / 1_000.0,
            avg_process_request_us: average(process_request_ns, total_requests) / 1_000.0,
            avg_write_response_us: average(write_response_ns, total_requests) / 1_000.0,
            avg_search_request_bytes: average(search_bytes_in, search_requests),
            avg_search_response_bytes: average(search_bytes_out, search_requests),
            avg_search_read_request_us: average(search_read_request_ns, search_requests) / 1_000.0,
            avg_search_process_request_us: average(search_process_request_ns, search_requests)
                / 1_000.0,
            avg_search_write_response_us: average(search_write_response_ns, search_requests)
                / 1_000.0,
        }
    }
}

impl RequestKind {
    fn is_search(self) -> bool {
        matches!(
            self,
            Self::SearchRequestCacheFastHit
                | Self::SearchRequestCacheEarlyHit
                | Self::SearchRequestCacheProcessHit
                | Self::SearchVectorCacheHit
                | Self::SearchFallback
        )
    }

    fn is_request_cache_hit(self) -> bool {
        matches!(
            self,
            Self::SearchRequestCacheFastHit
                | Self::SearchRequestCacheEarlyHit
                | Self::SearchRequestCacheProcessHit
        )
    }
}

fn read_request_standard(
    stream: &mut TcpStream,
    buffer: &mut Vec<u8>,
) -> io::Result<Option<ParsedRequest>> {
    let mut chunk = [0u8; 64 * 1024];

    loop {
        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
            let body_start = header_end + 4;
            let route = parse_route(buffer)?;
            let content_length =
                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
            let body_end = body_start + content_length;

            if buffer.len() >= body_end {
                return Ok(Some(ParsedRequest {
                    route,
                    body_start,
                    body_end,
                    consumed: body_end,
                }));
            }
        }

        let read = stream.read(&mut chunk)?;
        if read == 0 {
            if buffer.is_empty() {
                return Ok(None);
            }
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn read_request_with_early_cached_search(
    stream: &mut TcpStream,
    buffer: &mut Vec<u8>,
    db: &VectorDB,
    close_after_cached_search: bool,
    search_header_template: &mut Option<SearchHeaderTemplate>,
    early_cached_search_partial_read_bytes: usize,
) -> io::Result<Option<ReadOutcome>> {
    let mut chunk = [0u8; 64 * 1024];

    loop {
        if let Some(template) = search_header_template.as_ref() {
            if let Some((body_start, body_end)) = template.try_match(buffer) {
                let content_length = body_end - body_start;
                let prefix_end = body_start + usize::min(content_length, REQUEST_CACHE_PREFIX_LEN);
                if buffer.len() >= prefix_end {
                    if let Some(response) = db.cached_response_for_request_prefix(
                        content_length,
                        &buffer[body_start..prefix_end],
                    ) {
                        if buffer.len() >= body_end {
                            let response = if close_after_cached_search {
                                connection_close_response(&response)
                            } else {
                                response
                            };
                            return Ok(Some(ReadOutcome::CachedSearch(CachedSearchRequest {
                                consumed: body_end,
                                response,
                                keep_open: !close_after_cached_search,
                            })));
                        }
                    } else if buffer.len() >= body_end {
                        return Ok(Some(ReadOutcome::Parsed(ParsedRequest {
                            route: Route::Search,
                            body_start,
                            body_end,
                            consumed: body_end,
                        })));
                    }
                }
            }
        }

        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
            let body_start = header_end + 4;
            let route = parse_route(buffer)?;
            let content_length =
                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
            let body_end = body_start + content_length;

            if matches!(route, Route::Search) {
                if search_header_template.is_none() {
                    *search_header_template =
                        SearchHeaderTemplate::from_header(&buffer[..body_start]);
                }
                let prefix_end = body_start + usize::min(content_length, REQUEST_CACHE_PREFIX_LEN);
                if buffer.len() >= prefix_end {
                    if let Some(response) = db.cached_response_for_request_prefix(
                        content_length,
                        &buffer[body_start..prefix_end],
                    ) {
                        if !close_after_cached_search && buffer.len() < body_end {
                            let (response_header, response_body) = split_http_response(&response);
                            return Ok(Some(ReadOutcome::EarlyCachedSearch(
                                EarlyCachedSearchRequest {
                                    body_end,
                                    consumed: body_end,
                                    response_header,
                                    response_body,
                                },
                            )));
                        }

                        if buffer.len() >= body_end {
                            let response = if close_after_cached_search {
                                connection_close_response(&response)
                            } else {
                                response
                            };
                            return Ok(Some(ReadOutcome::CachedSearch(CachedSearchRequest {
                                consumed: body_end,
                                response,
                                keep_open: !close_after_cached_search,
                            })));
                        }
                    }
                }
            }

            if buffer.len() >= body_end {
                return Ok(Some(ReadOutcome::Parsed(ParsedRequest {
                    route,
                    body_start,
                    body_end,
                    consumed: body_end,
                })));
            }
        }

        let read_limit = limited_read_len(
            64 * 1024,
            buffer.len(),
            early_cached_search_partial_read_bytes,
        );
        let read = stream.read(&mut chunk[..read_limit])?;
        if read == 0 {
            if buffer.is_empty() {
                return Ok(None);
            }
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

#[inline(always)]
fn limited_read_len(chunk_len: usize, buffered_len: usize, partial_read_bytes: usize) -> usize {
    if partial_read_bytes == 0 || buffered_len >= partial_read_bytes {
        return chunk_len;
    }

    usize::min(chunk_len, partial_read_bytes - buffered_len)
}

fn finish_request_body(
    stream: &mut TcpStream,
    buffer: &mut Vec<u8>,
    body_end: usize,
) -> io::Result<()> {
    let mut chunk = [0u8; 64 * 1024];
    while buffer.len() < body_end {
        let read = stream.read(&mut chunk)?;
        if read == 0 {
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
    Ok(())
}

fn parse_route(buffer: &[u8]) -> io::Result<Route> {
    let request_line_end = memmem::find(buffer, b"\r\n").ok_or_else(bad_request_error)?;
    let request_line = &buffer[..request_line_end];
    let method_end = memchr(b' ', request_line).ok_or_else(bad_request_error)?;
    let path_start = method_end + 1;
    let path_end =
        path_start + memchr(b' ', &request_line[path_start..]).ok_or_else(bad_request_error)?;

    if &request_line[..method_end] != b"POST" {
        return Ok(Route::Unknown);
    }

    Ok(match &request_line[path_start..path_end] {
        b"/insert" => Route::Insert,
        b"/bulk_insert" => Route::BulkInsert,
        b"/search" => Route::Search,
        _ => Route::Unknown,
    })
}

fn parse_content_length(header_block: &[u8]) -> Option<usize> {
    let request_line_end = memmem::find(header_block, b"\r\n")?;
    let mut cursor = request_line_end + 2;

    while cursor < header_block.len() {
        let line_end = memmem::find(&header_block[cursor..], b"\r\n")
            .map(|line_end_rel| cursor + line_end_rel)
            .unwrap_or(header_block.len());
        let line = &header_block[cursor..line_end];
        if let Some(colon) = memchr(b':', line) {
            let name = &line[..colon];
            if name.eq_ignore_ascii_case(b"content-length") {
                let mut value = &line[colon + 1..];
                while matches!(value.first(), Some(b' ' | b'\t')) {
                    value = &value[1..];
                }

                }
                return parse_ascii_usize(value);
            }
        }
        cursor = line_end.saturating_add(2);
    }

    None
}

fn parse_ascii_usize(bytes: &[u8]) -> Option<usize> {
    if bytes.is_empty() {
        return None;
    }

    let mut value = 0usize;
    for &byte in bytes {
        if !byte.is_ascii_digit() {
            return None;
        }
        value = value.checked_mul(10)?.checked_add((byte - b'0') as usize)?;
    }
    Some(value)
}

impl SearchHeaderTemplate {
    fn from_header(header: &[u8]) -> Option<Self> {
        let content_length_pos = memmem::find(header, b"content-length:")?;
        let mut value_start = content_length_pos + b"content-length:".len();
        while matches!(header.get(value_start), Some(b' ' | b'\t')) {
            value_start += 1;
        }

        let mut value_end = value_start;
        while matches!(header.get(value_end), Some(byte) if byte.is_ascii_digit()) {
            value_end += 1;
        }

        let value_len = value_end.checked_sub(value_start)?;
        if value_len == 0 {
            return None;
        }

        Some(Self {
